export type ArchivedPost = {
  title: string;
  slug: string;
  category: string;
  /** Original publish date in ISO format (YYYY-MM-DD), when known. Omitted if the original date is unknown. */
  date?: string;
  readTime: string;
  excerpt: string;
  summary: string;
  content: string[];
};

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

/** Formats an ISO date (YYYY-MM-DD) as "May 31, 2023" via pure string parsing, so the result never shifts by a day due to time zones. */
export function formatIsoDate(iso: string): string {
  const [year, month, day] = iso.split("-").map(Number);
  return `${MONTH_NAMES[month - 1]} ${day}, ${year}`;
}

export function slugify(value: string) {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-+/g, "-");
}

